83	// readTree returns every regular file under dir, by slash-separated relative path.
84	func readTree(t *testing.T, dir string) map[string][]byte {
85		t.Helper()
86		files := map[string][]byte{}
87		err := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
88			if err != nil || d.IsDir() {
89				return err
90			}
91			rel, err := filepath.Rel(dir, path)
92			if err != nil {
93				return err
94			}
95			data, err := os.ReadFile(path)
96			if err != nil {
97				return err
98			}
99			files[filepath.ToSlash(rel)] = data
100			return nil
101		})
102		if err != nil {
103			t.Fatal(err)
104		}
105		return files
106	}
