108	func sha256Of(data []byte) string {
109		sum := sha256.Sum256(data)
110		return "sha256:" + hex.EncodeToString(sum[:])
111	}
112	
113	// blobPath is where an OCI layout keeps the blob of a digest.
114	func blobPath(digest string) string {
115		algo, hexa, _ := strings.Cut(digest, ":")
116		return "blobs/" + algo + "/" + hexa
117	}
