119	func decodeJSON(t *testing.T, name string, data []byte, out any) {
120		t.Helper()
121		if err := json.Unmarshal(data, out); err != nil {
122			t.Fatalf("%s is not valid JSON: %v\n%s", name, err, data)
123		}
124	}
