126	// blobOf returns the blob a descriptor points at, after checking that it exists
127	// and that its size and sha256 are the ones the descriptor states.
128	func blobOf(t *testing.T, tree map[string][]byte, d ociDescriptor) []byte {
129		t.Helper()
130		if !digestForm.MatchString(d.Digest) {
131			t.Fatalf("descriptor digest %q is not sha256:<64 hex>", d.Digest)
132		}
133		data, ok := tree[blobPath(d.Digest)]
134		if !ok {
135			t.Fatalf("the layout holds no blob %s for %s", blobPath(d.Digest), d.MediaType)
136		}
137		if int64(len(data)) != d.Size {
138			t.Errorf("blob %s is %d bytes, its descriptor says %d", d.Digest, len(data), d.Size)
139		}
140		if got := sha256Of(data); got != d.Digest {
141			t.Errorf("blob %s hashes to %s", d.Digest, got)
142		}
143		return data
144	}
